mapper.select:
SELECT a.work_file_pj_name AS workfilepjname, a.work_file_project AS workfileproject, SUM(a.work_file_total_amount) AS workfileamount FROM xft_bill_detail a JOIN xft_bill_info b ON a.work_file_id = b.bill_id
AND b.pay_finish_time BETWEEN #{workFileDoneStartTime} AND #{workFileDoneEndTime}
AND a.work_file_pj_name IN
#{project}
GROUP BY a.work_file_pj_name, a.work_file_project

mapper.insert:
UPDATE xft_bill_info
SET is_detail = 1
WHERE id = #{billInfo.id}
